USE MealPrepDB;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;
DECLARE @User INT,@Other INT,@Ingredient INT,@Unit INT,@Slot INT,@Recipe INT,@Session UNIQUEIDENTIFIER=NEWID(),@Job UNIQUEIDENTIFIER=NEWID(),@Operation UNIQUEIDENTIFIER=NEWID();
INSERT dbo.Users(Username,Email,PasswordHash) VALUES(N'assistant-fixture',N'assistant-fixture@example.invalid',N'synthetic-hash');SET @User=SCOPE_IDENTITY();
INSERT dbo.Users(Username,Email,PasswordHash) VALUES(N'assistant-other',N'assistant-other@example.invalid',N'synthetic-hash');SET @Other=SCOPE_IDENTITY();
SELECT TOP(1) @Ingredient=IngredientID FROM dbo.Ingredients ORDER BY IngredientID;
SELECT TOP(1) @Unit=UnitID FROM dbo.Units ORDER BY UnitID;
SELECT TOP(1) @Slot=CategoryID FROM dbo.Categories ORDER BY CategoryID;
DECLARE @Identity UNIQUEIDENTIFIER=(SELECT DatabaseID FROM dbo.ApplicationIdentity);
IF @Identity IS NULL THROW 51000,N'Missing stable database identity',1;
EXEC dbo.sp_AssistantPreferences @User,@Notice=N'gemini-free-1',@Accept=1;
EXEC dbo.sp_CreateDeviceSession @User,@Session,0x1111111111111111111111111111111111111111111111111111111111111111,N'synthetic-hash',N'Synthetic device';
DECLARE @Work NVARCHAR(MAX)=N'{"request":{"kind":"receipt","source":"fixture"},"context":{}}';
EXEC dbo.sp_AssistantJob N'create',@User,@Job,@Session,N'receipt',@Work;
EXEC dbo.sp_AssistantJob N'create',@User,@Job,@Session,N'receipt',@Work;
IF (SELECT COUNT(*) FROM dbo.AssistantJobs WHERE JobID=@Job)<>1 THROW 51000,N'Job retry duplicated inference',1;
EXEC dbo.sp_AssistantJob N'cancel',@Other,@Job;
IF (SELECT State FROM dbo.AssistantJobs WHERE JobID=@Job)<>N'Queued' THROW 51000,N'Foreign user cancelled job',1;
EXEC dbo.sp_AssistantJob N'claim';
EXEC dbo.sp_AssistantJob @Action=N'complete',@UserID=@User,@JobID=@Job,@Result=N'{"suggestions":[],"recipes":[],"meals":[],"purchases":[{"original":"Fixture","name":"Fixture"}],"warnings":[]}';
DECLARE @Version BIGINT=(SELECT Version FROM dbo.AssistantJobs WHERE JobID=@Job),@Purchases NVARCHAR(MAX)=(SELECT N'Fixture' AS name,@Ingredient AS ingredientId,CONVERT(DECIMAL(18,4),1.25) AS quantity,@Unit AS unitId,N'2030-04-01' AS purchasedOn FOR JSON PATH);
EXEC dbo.sp_AcceptReceipt @User,@Operation,@Job,@Version,N'[0]',@Purchases;
EXEC dbo.sp_AcceptReceipt @User,@Operation,@Job,@Version,N'[0]',@Purchases;
IF (SELECT COUNT(*) FROM dbo.AssistantAcceptedRows WHERE JobID=@Job)<>1 THROW 51000,N'Receipt retry duplicated purchases',1;
IF EXISTS(SELECT 1 FROM dbo.InventoryBatches WHERE UserID=@User) THROW 51000,N'Receipt acceptance changed pantry',1;
IF NOT EXISTS(SELECT 1 FROM dbo.ShoppingSnapshotItems i JOIN dbo.AssistantAcceptedRows a ON a.EntityID=i.ItemID WHERE a.JobID=@Job AND i.IsPurchased=1 AND i.PurchasedQuantity=1.25 AND i.ImportedAt IS NULL) THROW 51000,N'Reviewed purchase missing',1;
-- Build one recipe through the production procedure.
DECLARE @Ingredients NVARCHAR(MAX)=(SELECT @Ingredient AS IngredientID,@Unit AS UnitID,100 AS Quantity FOR JSON PATH);
DECLARE @Created TABLE(RecipeID INT);
INSERT @Created EXEC dbo.sp_CreateRecipe @User,@Slot,N'Assistant fixture',N'',N'Cook.',5,10,2,@Ingredients;
SELECT @Recipe=RecipeID FROM @Created;
DECLARE @RV VARCHAR(18)=(SELECT CONVERT(VARCHAR(18),CONVERT(BINARY(8),RowVersion),1) FROM dbo.Recipes WHERE RecipeID=@Recipe);
DECLARE @VersionPath NVARCHAR(30)=CONCAT(N'$."',@Recipe,N'"');
DECLARE @Recipes NVARCHAR(MAX)=JSON_MODIFY(N'{}',@VersionPath,@RV);
DECLARE @Meals NVARCHAR(MAX),@PlanOp UNIQUEIDENTIFIER=NEWID();
SET @Meals=(SELECT N'2030-04-01' AS date,@Slot AS slotId,@Recipe AS recipeId,1 AS portions,N'batch' AS batchKey FOR JSON PATH);
EXEC dbo.sp_ApplyReviewedPlan @User,@PlanOp,@Meals,N'[]',@Recipes,N'{}',N'{}';
EXEC dbo.sp_ApplyReviewedPlan @User,@PlanOp,@Meals,N'[]',@Recipes,N'{}',N'{}';
IF (SELECT COUNT(*) FROM dbo.MealPlanEntries WHERE UserID=@User)<>1 THROW 51000,N'Plan retry duplicated meals',1;
IF EXISTS(SELECT 1 FROM dbo.InventoryBatches WHERE UserID=@User) THROW 51000,N'Plan application deducted ingredients',1;
IF NOT EXISTS(SELECT 1 FROM dbo.AuditLog WHERE UserID=@User AND Action=N'PLAN_REVIEW_APPLY') THROW 51000,N'Missing plan audit',1;
-- Reviewed recipe provenance shares the recipe transaction and replays without duplication.
DECLARE @SourceOp UNIQUEIDENTIFIER=NEWID();
EXEC dbo.sp_SaveReviewedRecipe @UserID=@User,@OperationID=@SourceOp,@CategoryID=@Slot,@Title=N'Reviewed source fixture',@Description=N'',@Instructions=N'Cook.',@PrepTimeMinutes=5,@CookTimeMinutes=10,@Servings=2,@IngredientsJson=@Ingredients,@SourceText=N'Public recipe fixture',@SourceKind=N'import';
EXEC dbo.sp_SaveReviewedRecipe @UserID=@User,@OperationID=@SourceOp,@CategoryID=@Slot,@Title=N'Reviewed source fixture',@Description=N'',@Instructions=N'Cook.',@PrepTimeMinutes=5,@CookTimeMinutes=10,@Servings=2,@IngredientsJson=@Ingredients,@SourceText=N'Public recipe fixture',@SourceKind=N'import';
IF (SELECT COUNT(*) FROM dbo.Recipes WHERE UserID=@User AND Title=N'Reviewed source fixture')<>1 THROW 51000,N'Reviewed recipe retry duplicated recipe',1;
IF NOT EXISTS(SELECT 1 FROM dbo.RecipeSources s JOIN dbo.Recipes r ON r.RecipeID=s.RecipeID WHERE r.UserID=@User AND s.SourceText=N'Public recipe fixture') THROW 51000,N'Recipe provenance missing',1;
ROLLBACK;
PRINT N'Assistant identity, ownership, job/receipt/plan retries, explicit stock changes and audits verified.';
